Problem description
- There is a finite set of courses $$\mathcal{C}$$ and a finite set of academic categories $$\mathcal{K}$$, with course index $$c \in \mathcal{C}$$ and category index $$k \in \mathcal{K}$$.
- The planning problem is a single course-selection period over a horizon $$\mathcal{T}$$.
- Each course $$c$$ has a selection cost $$w_c$$, and the original objective is to minimize the total selection cost, which corresponds to minimizing the number of selected courses when all costs are unit costs.
- Each course may be eligible for one or more categories, described by an eligibility relation $$a_{ck}$$.
- Each category $$k$$ has a required minimum credit count $$d_k$$, meaning enough selected courses must be credited to that category.
- Some courses have prerequisite relations, described by a precedence relation $$r_{ij}$$, meaning course $$j$$ must also be selected whenever course $$i$$ is selected.
- A selected course may be credited to multiple categories if it is eligible for them, and it may satisfy more than one category requirement at the same time.
- The same selected course may not be counted more than once toward the same category requirement.
- The planning goal is to choose a smallest feasible set of courses that satisfies all category requirements and all prerequisite requirements.
- A solution is represented by:
  - $$x_c \in \{0,1\}$$ for each $$c \in \mathcal{C}$$, where $$x_c=1$$ means course $$c$$ is selected.
  - $$y_{ck} \in \{0,1\}$$ for each eligible pair $$\left(c,k\right)$$, where $$y_{ck}=1$$ means selected course $$c$$ is credited toward category $$k$$.
  - $$z$$, the total number of selected courses.

Input Format
{
  "course_count": "integer $$N$$, where $$N = \left|\mathcal{C}\right|$$",
  "category_count": "integer $$K$$, where $$K = \left|\mathcal{K}\right|$$",
  "time_horizon": {
    "symbol": "$$\mathcal{T}$$",
    "description": "single selection period"
  },
  "courses": [
    {
      "id": "integer in $$\\{0,1,\\dots,N-1\\}$$",
      "name": "string identifier of course $$c$$",
      "selection_cost": "cost parameter $$w_c$$",
      "eligible_categories": "subset of $$\\mathcal{K}$$ that course $$c$$ can satisfy",
      "prerequisites": "subset of $$\\mathcal{C}$$ that must be selected before course $$c$$"
    }
  ],
  "category_requirements": {
    "shape": "$$K$$",
    "entry": "$$d_k$$",
    "meaning": "minimum number of courses that must be credited to category $$k$$"
  },
  "eligibility_matrix": {
    "shape": "$$N \\times K$$",
    "entry": "$$a_{ck}$$",
    "meaning": "$$1$$ if course $$c$$ can satisfy category $$k$$, otherwise $$0$$"
  },
  "prerequisite_matrix": {
    "shape": "$$N \\times N$$",
    "entry": "$$r_{ij}$$",
    "meaning": "$$1$$ if course $$j$$ is a prerequisite of course $$i$$, otherwise $$0$$"
  }
}

Output Format
{
  "selected_courses": {
    "type": "array",
    "meaning": "the chosen subset $$S \\subseteq \\mathcal{C}$$ of courses"
  },
  "selection_vector": {
    "shape": "$$N$$",
    "meaning": "$$x_c$$ for each course $$c \\in \\mathcal{C}$$"
  },
  "category_credit_matrix": {
    "shape": "$$N \\times K$$",
    "meaning": "$$y_{ck}$$ indicating whether selected course $$c$$ is credited to category $$k$$"
  },
  "total_selected_courses": {
    "type": "integer",
    "meaning": "the total number of selected courses $$z$$"
  }
}

